const { DateTime } = require('luxon');

// ── CONFIG ────────────────────────────────────
const TZ         =  $('Config').first().json.TZ; // America/New_York;
const DAYS_AHEAD = $('Config').first().json.DAYS_AHEAD; // how many days to look forward
const WINDOW_START_H = $('Config').first().json.WINDOW_START_H;
const WINDOW_END_H   = $('Config').first().json.WINDOW_END_H;
// ─────────────────────────────────────────────

const now = DateTime.now().setZone(TZ);
const startDay = now.hour >= WINDOW_END_H
  ? now.startOf('day').plus({ days: 1 })
  : now.startOf('day');

return Array.from({ length: DAYS_AHEAD }, (_, i) => {
  const day = startDay.plus({ days: i });

  return {
    json: {
      date:         day.toISODate(),                // "2026-03-18"  — human readable, good for logs
      windowStart:  day.set({ hour: WINDOW_START_H, minute: 0, second: 0 }).toISO(),
      windowEnd:    day.set({ hour: WINDOW_END_H,   minute: 0, second: 0 }).toISO(),
      dayOfWeek:    day.weekday,                    // 1=Mon ... 7=Sun — use to skip weekends downstream
    }
  };
});

const { DateTime } = require('luxon');

// ── CONFIG ────────────────────────────────────
const TZ       = 'Africa/Casablanca';//'America/New_York';
const SLOT_MIN = 30;
// ─────────────────────────────────────────────

// ── 1. WINDOW BOUNDARIES FROM LOOP ───────────
const loopItem    = $('Loop Over Items').first().json;
const windowStart = DateTime.fromISO(loopItem.windowStart).setZone(TZ);
const windowEnd   = DateTime.fromISO(loopItem.windowEnd).setZone(TZ);

const totalSlots = windowEnd.diff(windowStart, 'minutes').minutes / SLOT_MIN;


// ── 2. GENERATE ALL SLOTS ─────────────────────
const allSlots = Array.from({ length: totalSlots }, (_, i) => ({
  start: windowStart.plus({ minutes: i * SLOT_MIN }),
  end:   windowStart.plus({ minutes: (i + 1) * SLOT_MIN }),
}));


// ── 3. PARSE ALL EVENTS ───────────────────────
// All events within window — used for occupied epoch set.
// Includes Cal.com bookings, email invites, recurring blocks.
// Cal.com already hides real events via primary calendar conflict check,
// so we only write BLOCKED events for empty slots that need hiding.
const allEvents = $('Get primary events').all()
  .filter(i => i.json?.start?.dateTime)
  .map(i => i.json)
  .filter(e => {
    const start = DateTime.fromISO(e.start.dateTime).setZone(TZ);
    const end   = DateTime.fromISO(e.end.dateTime).setZone(TZ);
    return start < windowEnd && end > windowStart;
  });

// Only Cal.com bookings shape the cluster.
// Invites and recurring events are walls — they block themselves
// through Cal.com's primary calendar conflict check, never touch cluster logic.
const clientSessions = allEvents.filter(e =>
  e.iCalUID?.endsWith('@Cal.com')
);

// All events occupy slots regardless of source — excluded from BLOCKED output.
const occupiedEpochs = new Set(
  allEvents.map(e => DateTime.fromISO(e.start.dateTime).setZone(TZ).toMillis())
);


// ── 4. CLUSTER LOGIC ──────────────────────────
let slotsToBlock = [];

if (clientSessions.length === 0) {

  // STATE 1 — Empty day
  // Show first 2 adjacent slots (windowStart and windowStart+30),
  // block everything else. 2 adjacent slots makes fragmentation
  // geometrically impossible even if two clients book simultaneously.
  slotsToBlock = allSlots.slice(2);

  console.log(
    `${loopItem.date} | State 1 (empty)`,
    `| Visible: ${windowStart.toFormat('HH:mm')} and ${windowStart.plus({ minutes: SLOT_MIN }).toFormat('HH:mm')}`,
    `| Blocking: ${slotsToBlock.length} slots`
  );

} else {

  // STATE 2 — Cluster active
  // All arithmetic in epoch ms — avoids timezone string comparison bugs.
  const startEpochs = clientSessions.map(s => DateTime.fromISO(s.start.dateTime).toMillis());
  const endEpochs   = clientSessions.map(s => DateTime.fromISO(s.end.dateTime).toMillis());

  const clusterStart = DateTime.fromMillis(Math.min(...startEpochs)).setZone(TZ);
  const clusterEnd   = DateTime.fromMillis(Math.max(...endEpochs)).setZone(TZ);

  // One slot before cluster (if inside window)
  const beforeStart = clusterStart.minus({ minutes: SLOT_MIN });
  const beforeValid = beforeStart.toMillis() >= windowStart.toMillis();

  // One slot after cluster (if inside window)
  const afterStart = clusterEnd;
  const afterValid = afterStart.plus({ minutes: SLOT_MIN }).toMillis() <= windowEnd.toMillis();

  // Block everything that isn't the before or after slot
  slotsToBlock = allSlots.filter(slot => {
    const ms = slot.start.toMillis();
    if (beforeValid && ms === beforeStart.toMillis()) return false;
    if (afterValid  && ms === afterStart.toMillis())  return false;
    return true;
  });

  console.log(
    `${loopItem.date} | State 2 (cluster active)`,
    `| Cluster: ${clusterStart.toFormat('HH:mm')}–${clusterEnd.toFormat('HH:mm')}`,
    `| Before: ${beforeValid ? beforeStart.toFormat('HH:mm') : 'none (wall)'}`,
    `| After: ${afterValid ? afterStart.toFormat('HH:mm') : 'none (wall)'}`,
    `| Blocking: ${slotsToBlock.length} slots`
  );
}


// ── 5. STRIP OCCUPIED SLOTS + TAG REASON ─────
// Split into two buckets instead of just filtering
const blocks = slotsToBlock
  .filter(slot => !occupiedEpochs.has(slot.start.toMillis()))
  .map(slot => ({
    json: {
      date: loopItem.date,
      type: 'blocking',
      start: { dateTime: slot.start.toISO(), timeZone: TZ },
      end: { dateTime: slot.end.toISO(), timeZone: TZ },
    }
  }));

const primary = allSlots
  .filter(slot => occupiedEpochs.has(slot.start.toMillis()))
  .map(slot => ({
    json: {
      date: loopItem.date,
      type: 'primary',     // real event on primary calendar, Cal.com handles this itself
      start: { dateTime: slot.start.toISO(), timeZone: TZ },
      end: { dateTime: slot.end.toISO(),   timeZone: TZ },
    }
  }));

return [...blocks, ...primary];
